import heapq

def match(orders):
    book = {}  # id -> dict with side, price, qty, seq, active(bool)
    sell_heap = []  # (price, seq, id) - min-heap by price then seq
    buy_heap = []   # (-price, seq, id) - max-heap by price (min-heap on -price) then seq
    trades = []
    seq_counter = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        else:  # market
            _, oid, side, qty = o
            price = None

        seq_counter += 1
        seq = seq_counter
        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            # clean up invalid entries from top of opp_heap
            while opp_heap:
                top = opp_heap[0]
                if side == 'buy':
                    p, s, oid2 = top
                else:
                    negp, s, oid2 = top
                    p = -negp
                info = book.get(oid2)
                if info is None or not info['active'] or info['qty'] <= 0:
                    heapq.heappop(opp_heap)
                    continue
                break

            if not opp_heap:
                break

            if side == 'buy':
                p, s, oid2 = opp_heap[0]
            else:
                negp, s, oid2 = opp_heap[0]
                p = -negp

            info = book[oid2]

            if typ == 'market':
                cond = True
            else:
                if side == 'buy':
                    cond = price >= p
                else:
                    cond = price <= p

            if not cond:
                break

            trade_qty = min(remaining, info['qty'])

            if side == 'buy':
                trades.append([oid, oid2, p, trade_qty])
            else:
                trades.append([oid2, oid, p, trade_qty])

            remaining -= trade_qty
            info['qty'] -= trade_qty

            if info['qty'] == 0:
                info['active'] = False
                heapq.heappop(opp_heap)
            # else partially filled resting order keeps its place; loop will re-check cond

        book[oid] = {
            'side': side,
            'price': price,
            'qty': remaining,
            'seq': seq,
            'active': remaining > 0
        }

        if typ == 'limit' and remaining > 0:
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))
        else:
            # ioc/market leftover discarded, or limit fully filled -> not active/resting
            book[oid]['active'] = False

    return trades

